-- Ensure the existence of the football database and create if necessary
CREATE DATABASE IF NOT EXISTS football;

-- Use the football database
USE football;

-- CREATE TEAMS TABLE
CREATE TABLE TEAMS (
    TEAM_ID INT PRIMARY KEY AUTO_INCREMENT,
    TEAM_NAME VARCHAR(255) NOT NULL,
    HOME_STADIUM VARCHAR(255) NOT NULL,
    UNIQUE KEY UQ_TEAM_NAME (TEAM_NAME)
);

-- INSERT TEAMS INTO TEAMS TABLE
-- (These 10 clubs are the E-Fiiri League demo roster and also, per
-- textbaseleagueformat.md, Hargeysa's First Division 2023/24 clubs -
-- team #3 is renamed to disambiguate it from the other "Dawladda Hoose"
-- clubs from other towns introduced below.)
