       (10, 'Ganacsiga FC', 'Ganacsiga Stadium');

-- CREATE COMPETITIONS TABLE
-- A competition is one season of one tournament: a flat round-robin
-- LEAGUE (with optional REGION/DIVISION_LEVEL), a GROUP_KNOCKOUT
-- competition (group stage feeding a knockout bracket), or a knockout CUP.
CREATE TABLE COMPETITIONS (
    COMPETITION_ID INT PRIMARY KEY AUTO_INCREMENT,
    NAME VARCHAR(255) NOT NULL,
    TYPE ENUM('LEAGUE', 'GROUP_KNOCKOUT', 'CUP') NOT NULL,
    SEASON VARCHAR(20) NOT NULL,
    REGION VARCHAR(100) DEFAULT NULL,
    DIVISION_LEVEL INT DEFAULT NULL,
    UNIQUE KEY UQ_COMPETITION_NAME (NAME)
);

-- CREATE COMPETITION_TEAMS TABLE
-- Which teams play in which competition, and (for group-stage
-- competitions) which group they were drawn into.
CREATE TABLE COMPETITION_TEAMS (
    COMPETITION_ID INT NOT NULL,
    TEAM_ID INT NOT NULL,
    GROUP_NAME VARCHAR(10) DEFAULT NULL,
    PRIMARY KEY (COMPETITION_ID, TEAM_ID),
    FOREIGN KEY (COMPETITION_ID) REFERENCES COMPETITIONS(COMPETITION_ID),
    FOREIGN KEY (TEAM_ID) REFERENCES TEAMS(TEAM_ID)
);

-- CREATE STANDINGS TABLE (replaces the old single-league LEAGUE table)
-- One row per team per competition (+ group, for group-stage competitions).
-- GOAL_DIFF is used instead of GOALS_FOR/GOALS_AGAINST for the handful of
-- historical tables that only ever reported an aggregate goal difference.
CREATE TABLE STANDINGS (
    STANDING_ID INT PRIMARY KEY AUTO_INCREMENT,
    COMPETITION_ID INT NOT NULL,
    TEAM_ID INT NOT NULL,
    GROUP_NAME VARCHAR(10) DEFAULT NULL,
    WON INT DEFAULT 0,
    DRAW INT DEFAULT 0,
    LOST INT DEFAULT 0,
    GOALS_FOR INT DEFAULT NULL,
    GOALS_AGAINST INT DEFAULT NULL,
    GOAL_DIFF INT DEFAULT NULL,
    POINTS INT DEFAULT 0,
    STATUS VARCHAR(100) DEFAULT NULL,
    UNIQUE KEY UQ_STANDING (COMPETITION_ID, TEAM_ID),
    FOREIGN KEY (COMPETITION_ID) REFERENCES COMPETITIONS(COMPETITION_ID),
    FOREIGN KEY (TEAM_ID) REFERENCES TEAMS(TEAM_ID)
);

-- Create PLAYER Table
CREATE TABLE PLAYER (
    PLAYER_ID INT PRIMARY KEY AUTO_INCREMENT,
    FNAME VARCHAR(255) NOT NULL,
    MNAME VARCHAR(255),
    LNAME VARCHAR(255) NOT NULL,
    DOB DATE,
    POSITION VARCHAR(50),
    WEIGHT INT,
    HEIGHT INT,
    NATIONALITY VARCHAR(255),
    KIT_NUMBER INT,
    TEAM_ID INT,
    CONTRACT_ID INT,
    FOREIGN KEY (TEAM_ID) REFERENCES TEAMS(TEAM_ID)
);



CREATE TABLE fixtures (
    FIXTURE_ID INT PRIMARY KEY AUTO_INCREMENT,
    COMPETITION_ID INT NOT NULL,
    GROUP_NAME VARCHAR(10) DEFAULT NULL,
    ROUND_NAME VARCHAR(50) DEFAULT NULL,
    ROUND_ORDER INT DEFAULT 0,
    HOME_TEAM_ID INT NOT NULL,
    AWAY_TEAM_ID INT NOT NULL,
    MATCH_DATE DATE NOT NULL,
    VENUE VARCHAR(255) NOT NULL,
    HOME_SCORE INT DEFAULT NULL,
    AWAY_SCORE INT DEFAULT NULL,
    HOME_PENALTIES INT DEFAULT NULL,
    AWAY_PENALTIES INT DEFAULT NULL,
    WINNER_TEAM_ID INT DEFAULT NULL,
    NOTE VARCHAR(255) DEFAULT NULL,
    FOREIGN KEY (COMPETITION_ID) REFERENCES COMPETITIONS(COMPETITION_ID),
    FOREIGN KEY (HOME_TEAM_ID) REFERENCES teams(TEAM_ID),
    FOREIGN KEY (AWAY_TEAM_ID) REFERENCES teams(TEAM_ID),
    FOREIGN KEY (WINNER_TEAM_ID) REFERENCES teams(TEAM_ID)
);


